{"command": "python3 -c "
from scapy.all import *
pkts = rdpcap('capture.pcapng')
for p in pkts:
    if TCP in p and Raw in p:
        payload = bytes(p[Raw].load)
        # Chercher des chaînes ASCII
        s = ''.join(chr(b) if 32 <= b < 127 else '.' for b in payload)
        if len(s) > 10:
            print(f'{p[IP].src}:{p[TCP].sport} -> {p[IP].dst}:{p[TCP].dport} ({len(payload)} bytes): {s[:200]}')
" 2>/dev/null | head -50"}
